import{_ as t,o as s,c as d,a3 as o}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"Central Playwright E2E","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Central Playwright E2E | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/playwright"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Central Playwright E2E | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/playwright"}]]},"headers":[],"relativePath":"developer-guide/playwright.md","filePath":"developer-guide/playwright.md","lastUpdated":1785700928000}'),n={name:"developer-guide/playwright.md"};function a(r,e,c,i,p,l){return s(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="central-playwright-e2e" tabindex="-1">Central Playwright E2E <a class="header-anchor" href="#central-playwright-e2e" aria-label="Permalink to &quot;Central Playwright E2E&quot;">​</a></h1><p>The Playwright suite for the <strong>Central Application</strong> lives in the Frontend repository:</p><ul><li>Guide: <a href="https://github.com/DiligentCreators/SaaS-Frontend/blob/main/docs/testing/PLAYWRIGHT.md" target="_blank" rel="noreferrer"><code>SaaS-Frontend/docs/testing/PLAYWRIGHT.md</code></a></li><li>Tests: <code>SaaS-Frontend/e2e/tests/&lt;module&gt;/</code></li><li>Shared POM / fixtures: <code>SaaS-Frontend/e2e/{pages,fixtures,helpers,utils,test-data}/</code></li><li>Config: <code>SaaS-Frontend/playwright.config.ts</code></li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Covers Platform/Core only: auth, dashboard, tenants (workspaces), users, roles, permissions matrix, modules, marketplace, billing (Billing nav + payment gateways + settings billing tab + tenant invoice/payment tabs), impersonation, settings, profile, smoke, and regression.</p><p>Does <strong>not</strong> cover Stripe Checkout or future ERP modules beyond what is listed below. Tenant Settings branding/mail coverage lives in <code>e2e/tests/settings/tenant-settings.spec.ts</code>. Tenant Users/Roles RBAC coverage lives in <code>e2e/tests/users/tenant-users.spec.ts</code> (<code>npm run test:e2e:tenant-rbac</code>). <strong>Leads</strong> product UI: <code>e2e/tests/leads/</code> (<code>npm run test:e2e:leads</code>). <strong>Tasks</strong> product UI: <code>e2e/tests/tasks/</code> (<code>npm run test:e2e:tasks</code>). <strong>ToDos</strong> product UI: <code>e2e/tests/todos/</code> (<code>npm run test:e2e:todos</code>). <strong>Contacts</strong> product UI: <code>e2e/tests/contacts/</code> (<code>npm run test:e2e:contacts</code>). <strong>Companies</strong> product UI: <code>e2e/tests/companies/</code> (<code>npm run test:e2e:companies</code>). <strong>Opportunities / Quotations / Contracts</strong>: <code>e2e/tests/{opportunities,quotations,contracts}/</code> plus shared-session <code>e2e/tests/sales/</code> (<code>npm run test:e2e:sales</code>). <strong>Invoices</strong>: <code>e2e/tests/invoices/</code> (<code>npm run test:e2e:invoices</code>). <strong>Payments</strong>: <code>e2e/tests/payments/</code> (<code>npm run test:e2e:payments</code>) — installs both <code>invoices</code> and <code>payments</code> modules (hard dependency). <strong>Credit Notes</strong>: <code>e2e/tests/credit-notes/</code> (<code>npm run test:e2e:credit-notes</code>) — installs both <code>invoices</code> and <code>credit-notes</code> modules (hard dependency). <strong>Estimates</strong>: <code>e2e/tests/estimates/</code> (<code>npm run test:e2e:estimates</code>) — installs both <code>invoices</code> and <code>estimates</code> modules (hard dependency), covers create → send → accept → convert to invoice. <strong>Vendors</strong>: <code>e2e/tests/vendors/</code> (<code>npm run test:e2e:vendors</code>) — installs the <code>vendors</code> module (free Purchasing opt-in), covers list KPIs, create, notes, and activity timeline. <strong>Purchase Orders</strong>: <code>e2e/tests/purchase-orders/</code> (<code>npm run test:e2e:purchase-orders</code>) — installs both <code>vendors</code> and <code>purchase-orders</code> modules (hard dependency), covers create, status transitions (draft → sent → partially received → received), and the timeline. <strong>Expenses</strong>: <code>e2e/tests/expenses/</code> (<code>npm run test:e2e:expenses</code>) — installs <code>vendors</code> + <code>purchase-orders</code> + <code>expenses</code> (all soft/free Purchasing opt-ins, no hard dependency), covers list KPIs, create → submit → approve → pay, and converting a purchase order to a draft expense via the PO detail sheet. <strong>Communication Templates</strong>: <code>e2e/tests/communication-templates/</code> (<code>npm run test:e2e:communication-templates</code>). Tenant suites use Playwright project <code>tenant</code>.</p><h2 id="spec-directories-independently-runnable" tabindex="-1">Spec directories (independently runnable) <a class="header-anchor" href="#spec-directories-independently-runnable" aria-label="Permalink to &quot;Spec directories (independently runnable)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Path</th><th>npm script</th></tr></thead><tbody><tr><td>Auth</td><td><code>e2e/tests/auth/</code></td><td><code>npm run test:e2e:auth</code></td></tr><tr><td>Dashboard</td><td><code>e2e/tests/dashboard/</code></td><td><code>npm run test:e2e:dashboard</code></td></tr><tr><td>Tenants / workspaces</td><td><code>e2e/tests/tenants/</code></td><td><code>npm run test:e2e:tenants</code></td></tr><tr><td>Users</td><td><code>e2e/tests/users/</code></td><td><code>npm run test:e2e:users</code> (Central) · <code>npm run test:e2e:tenant-rbac</code> (workspace Users/Roles)</td></tr><tr><td>Roles</td><td><code>e2e/tests/roles/</code></td><td><code>npm run test:e2e:roles</code></td></tr><tr><td>Permissions</td><td><code>e2e/tests/permissions/</code></td><td><code>npm run test:e2e:permissions</code></td></tr><tr><td>Modules</td><td><code>e2e/tests/modules/</code></td><td><code>npm run test:e2e:modules</code></td></tr><tr><td>Marketplace</td><td><code>e2e/tests/marketplace/</code></td><td><code>npm run test:e2e:marketplace</code></td></tr><tr><td>Billing</td><td><code>e2e/tests/billing/</code></td><td><code>npm run test:e2e:billing</code></td></tr><tr><td>Impersonation</td><td><code>e2e/tests/impersonation/</code></td><td><code>npm run test:e2e:impersonation</code></td></tr><tr><td>Settings</td><td><code>e2e/tests/settings/</code></td><td><code>npm run test:e2e:settings</code> — Central identity/flags + <code>tenant-settings.spec.ts</code> workspace branding/mail fallback (<code>npm run test:e2e:tenant-settings</code>)</td></tr><tr><td>Leads</td><td><code>e2e/tests/leads/</code></td><td><code>npm run test:e2e:leads</code></td></tr><tr><td>Tasks</td><td><code>e2e/tests/tasks/</code></td><td><code>npm run test:e2e:tasks</code></td></tr><tr><td>Contacts</td><td><code>e2e/tests/contacts/</code></td><td><code>npm run test:e2e:contacts</code></td></tr><tr><td>Companies</td><td><code>e2e/tests/companies/</code></td><td><code>npm run test:e2e:companies</code></td></tr><tr><td>Opportunities</td><td><code>e2e/tests/opportunities/</code></td><td><code>npm run test:e2e:opportunities</code></td></tr><tr><td>Quotations</td><td><code>e2e/tests/quotations/</code></td><td><code>npm run test:e2e:quotations</code></td></tr><tr><td>Contracts</td><td><code>e2e/tests/contracts/</code></td><td><code>npm run test:e2e:contracts</code></td></tr><tr><td>Sales (shared session)</td><td><code>e2e/tests/sales/</code></td><td><code>npm run test:e2e:sales</code> / <code>test:e2e:sales:headed</code></td></tr><tr><td>Invoices</td><td><code>e2e/tests/invoices/</code></td><td><code>npm run test:e2e:invoices</code></td></tr><tr><td>Payments</td><td><code>e2e/tests/payments/</code></td><td><code>npm run test:e2e:payments</code></td></tr><tr><td>Credit Notes</td><td><code>e2e/tests/credit-notes/</code></td><td><code>npm run test:e2e:credit-notes</code></td></tr><tr><td>Estimates</td><td><code>e2e/tests/estimates/</code></td><td><code>npm run test:e2e:estimates</code></td></tr><tr><td>Vendors</td><td><code>e2e/tests/vendors/</code></td><td><code>npm run test:e2e:vendors</code> / <code>test:e2e:vendors:headed</code></td></tr><tr><td>Purchase Orders</td><td><code>e2e/tests/purchase-orders/</code></td><td><code>npm run test:e2e:purchase-orders</code> / <code>test:e2e:purchase-orders:headed</code></td></tr><tr><td>Expenses</td><td><code>e2e/tests/expenses/</code></td><td><code>npm run test:e2e:expenses</code> / <code>test:e2e:expenses:headed</code></td></tr><tr><td>Purchasing (shared session)</td><td><code>e2e/tests/purchasing/</code></td><td><code>npm run test:e2e:purchasing</code> / <code>test:e2e:purchasing:headed</code> — one login, then Vendors → Purchase Orders → Expenses with form validation + PO convert; includes negative authz (<code>purchasing.authz.spec.ts</code>)</td></tr><tr><td>Communication Templates</td><td><code>e2e/tests/communication-templates/</code></td><td><code>npm run test:e2e:communication-templates</code></td></tr><tr><td>Profile</td><td><code>e2e/tests/profile/</code></td><td><code>npm run test:e2e:profile</code></td></tr><tr><td>Smoke</td><td><code>e2e/tests/smoke/</code></td><td><code>npm run test:e2e:smoke</code></td></tr><tr><td>Regression</td><td><code>e2e/tests/regression/</code></td><td><code>npm run test:e2e:regression</code></td></tr></tbody></table><p>Setup project (<code>auth.setup.ts</code>) authenticates once for chromium suites. Auth and <strong>tenant</strong> projects use empty storage and do not depend on setup.</p><h2 id="qa-status-central-stabilization" tabindex="-1">QA status (Central stabilization) <a class="header-anchor" href="#qa-status-central-stabilization" aria-label="Permalink to &quot;QA status (Central stabilization)&quot;">​</a></h2><ul><li>Full suite: <strong>48 passed</strong>, 0 skipped, 0 failed (local Chromium run).</li><li>Each module directory is executable independently via <code>npx playwright test e2e/tests/&lt;module&gt;</code> or the npm scripts above.</li><li>After module-level green runs, re-run <code>npm run test:e2e</code> before declaring Central stable.</li></ul><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>Playwright writes generated screenshots under:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SaaS-Frontend/docs/testing/images/</span></span>
<span class="line"><span>SaaS-Frontend/test-results/</span></span>
<span class="line"><span>SaaS-Frontend/playwright-report/</span></span></code></pre></div><p>Those paths are <strong>gitignored</strong> in Frontend and Backend — never commit e2e-generated images, videos, or traces there.</p><p>Curated documentation screenshots may be committed <strong>only</strong> in this Docs repo (<code>testing/images/…</code>) when intentionally documenting a workflow. Do not dump raw Playwright run output into Docs.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SaaS-Frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.e2e.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.e2e</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:report</span></span></code></pre></div><p>See the Frontend guide for environment variables, CI usage, debugging, and extension patterns.</p>`,19)])])}const m=t(n,[["render",a]]);export{u as __pageData,m as default};
